        self._call_fn = _call_claude if provider == "claude" else _call_openai

    def _truncate(self, text):
        words = text.split()
        approx_tokens = int(self.max_seq_len * 0.75)
        if len(words) > approx_tokens:
            words = words[:approx_tokens]
        return " ".join(words)

